// What did the readiness check see?
//   200            -> healthy
//   503 (or other) -> the backend runs, but a dependency (Google Sheets) is not usable
//   no answer      -> the backend is not running, or too slow
const res = $input.first().json;
let health;
if (res.error) {
  health = { ok: false, problem: 'BACKEND_UNREACHABLE', detail: 'The backend did not answer (not running, or slower than 10 s).' };
} else if (res.statusCode === 200) {
  health = { ok: true };
} else {
  const err = (res.body && res.body.error) || {};
  health = { ok: false, problem: err.code || `HTTP_${res.statusCode}`, detail: err.message || 'The backend answered but is not ready.' };
}

// Static data survives between runs, but ONLY for automatic (published) runs,
// not when you click "Execute workflow" by hand.
const state = $getWorkflowStaticData('global');
const now = new Date();

if (!health.ok && !state.down) {
  state.down = { since: now.toISOString(), problem: health.problem };
  return [{ json: { action: 'alert', ...health, since: state.down.since } }];
}
if (!health.ok) {
  return [{ json: { action: 'still_down', ...health, since: state.down.since } }];
}
if (state.down) {
  const minutes = Math.max(1, Math.round((now - new Date(state.down.since)) / 60000));
  const problem = state.down.problem;
  delete state.down;
  return [{ json: { action: 'recovered', minutes, problem } }];
}
return [{ json: { action: 'quiet' } }];

// Did the backend accept it? 2xx → continue with its answer (the JSON body).
// Anything else FAILS this run (→ WF4 escalates), labelled so a person knows what to do:
//   TEMPORARY (408, 429, 5xx): the backend had a problem; trying again later can work
//   PERMANENT (other 4xx):     retrying can never fix it, so it is NOT retried
// "No answer at all" never gets here: the HTTP node already retried that 3 times.
const r = $input.first().json;
const s = r.statusCode;
if (s >= 200 && s < 300) return [{ json: r.body ?? {} }];
const code = (r.body && r.body.error && r.body.error.code) || 'no error code';
const temporary = s === 408 || s === 429 || (s >= 500 && s <= 599);
throw new Error((temporary ? 'TEMPORARY' : 'PERMANENT') + ' backend answer to "Record the outage" - HTTP ' + s + ' ' + code + (temporary ? '' : ' (not retried, retrying cannot fix it)'));
